//! Source options are presentation-only drafts, captured before asset IO.
use eframe::egui;
use skylive_core::{SlideShowCanvas,SlideShowBehavior,SlideShowMode};
#[derive(Clone,Copy,PartialEq)]enum CanvasMode{Auto,Resolution,Aspect}
pub struct Draft{pub playback_mode:SlideShowMode,mode:CanvasMode,width:String,height:String,pub behavior:SlideShowBehavior}
impl Draft{
    pub fn modern()->Self{Self{playback_mode:SlideShowMode::Automatic,mode:CanvasMode::Resolution,width:"1920".into(),height:"1080".into(),behavior:SlideShowBehavior::AlwaysPlay}}
    pub fn from_settings(settings:&skylive_core::ImageSlideShow)->Self{let mut draft=Self::modern();draft.behavior=settings.behavior();draft.playback_mode=settings.mode();match settings.canvas(){SlideShowCanvas::Auto=>draft.mode=CanvasMode::Auto,SlideShowCanvas::Resolution{width,height}=>{draft.mode=CanvasMode::Resolution;draft.width=width.to_string();draft.height=height.to_string();},SlideShowCanvas::Aspect{width,height}=>{draft.mode=CanvasMode::Aspect;draft.width=width.to_string();draft.height=height.to_string();}}draft}
    pub fn canvas(&self)->Result<SlideShowCanvas,String>{if self.mode==CanvasMode::Auto{return Ok(SlideShowCanvas::Auto);}let width=self.width.parse::<u32>().map_err(|_|"Enter whole slideshow canvas or aspect values from 1 to 8192.".to_owned())?;let height=self.height.parse::<u32>().map_err(|_|"Enter whole slideshow canvas or aspect values from 1 to 8192.".to_owned())?;let value=if self.mode==CanvasMode::Resolution{SlideShowCanvas::Resolution{width,height}}else{SlideShowCanvas::Aspect{width,height}};value.validate().map_err(|e|e.to_string())?;Ok(value)}
}
fn mode_text(mode:CanvasMode)->&'static str{match mode{CanvasMode::Auto=>"Automatic image canvas",CanvasMode::Resolution=>"Custom resolution",CanvasMode::Aspect=>"Custom aspect ratio"}}
pub fn editor(ui:&mut egui::Ui,draft:&mut Draft,raw:Option<(u32,u32)>){
    let caption=ui.label(crate::i18n::tr(ui,"Slideshow Playback Mode"));egui::ComboBox::from_id_salt("slideshow-playback-mode").selected_text(crate::i18n::tr(ui,draft.playback_mode.label())).show_ui(ui,|ui|{for mode in[SlideShowMode::Automatic,SlideShowMode::Manual]{ui.selectable_value(&mut draft.playback_mode,mode,crate::i18n::tr(ui,mode.label())).on_hover_text(crate::i18n::tr(ui,"Automatic advances at the configured interval. Manual holds the slide for Previous and Next. Play temporarily enables automatic playback; Pause enables manual playback."));}}).response.labelled_by(caption.id).on_hover_text(crate::i18n::tr(ui,"The saved mode sets the initial transport state. Playback buttons change runtime state without editing this draft or scene history."));
    ui.separator();let caption=ui.label(crate::i18n::tr(ui,"Slideshow Canvas"));egui::ComboBox::from_id_salt("slideshow-canvas-mode").selected_text(crate::i18n::tr(ui,mode_text(draft.mode))).show_ui(ui,|ui|{for mode in[CanvasMode::Auto,CanvasMode::Resolution,CanvasMode::Aspect]{ui.selectable_value(&mut draft.mode,mode,crate::i18n::tr(ui,mode_text(mode))).on_hover_text(crate::i18n::tr(ui,"Automatic uses the largest image dimensions. Resolution sets the output canvas. Aspect expands that canvas without stretching images."));}}).response.labelled_by(caption.id).on_hover_text(crate::i18n::tr(ui,"Automatic uses the largest image dimensions. Resolution sets the output canvas. Aspect expands that canvas without stretching images."));
    if draft.mode!=CanvasMode::Auto{
        ui.horizontal_wrapped(|ui|{let caption=ui.label(crate::i18n::tr(ui,"Canvas Preset"));egui::ComboBox::from_id_salt("slideshow-canvas-preset").selected_text(crate::i18n::tr(ui,"Choose a preset or edit values")).show_ui(ui,|ui|{let presets:&[(u32,u32)]=if draft.mode==CanvasMode::Resolution{&[(1920,1080),(1280,720),(2560,1440),(3840,2160),(1080,1920)]}else{&[(16,9),(16,10),(4,3),(1,1)]};for &(width,height)in presets{let text=format!("{width}{}{height}",if draft.mode==CanvasMode::Resolution{" × "}else{" : "});if ui.selectable_label(draft.width.parse::<u32>().ok()==Some(width)&&draft.height.parse::<u32>().ok()==Some(height),text).on_hover_text(crate::i18n::tr(ui,"Set these values in the draft. Apply is still required.")).clicked(){draft.width=width.to_string();draft.height=height.to_string();}}}).response.labelled_by(caption.id).on_hover_text(crate::i18n::tr(ui,"Set these values in the draft. Apply is still required."));});
        ui.horizontal_wrapped(|ui|{for(label,value,id)in[("Width / aspect numerator",&mut draft.width,"slideshow-canvas-width"),("Height / aspect denominator",&mut draft.height,"slideshow-canvas-height")]{let caption=ui.label(crate::i18n::tr(ui,label));ui.add(egui::TextEdit::singleline(value).char_limit(5).desired_width(82.0).id_salt(id)).labelled_by(caption.id).on_hover_text(crate::i18n::tr(ui,"Use whole values from 1 to 8192. The resolved canvas must stay within the existing 16M-pixel image budget."));}});
    }
    let resolved=draft.canvas().and_then(|canvas|match canvas{SlideShowCanvas::Resolution{width,height}=>Ok(Some((width,height))),_=>raw.map(|raw|canvas.resolve(raw).map_err(|e|e.to_string())).transpose()});
    match resolved{Ok(Some((width,height)))=>{ui.small(crate::i18n::tf(ui,"Slideshow output: {width} × {height}",&[("{width}",width.to_string()),("{height}",height.to_string())]));},Err(error)=>{ui.colored_label(ui.visuals().error_fg_color,crate::i18n::tr(ui,error));},_=>{ui.small(crate::i18n::tr(ui,"Automatic and aspect output dimensions are resolved after the image files are prepared."));}}
    let caption=ui.label(crate::i18n::tr(ui,"Slideshow Visibility"));egui::ComboBox::from_id_salt("slideshow-visibility").selected_text(crate::i18n::tr(ui,draft.behavior.label())).show_ui(ui,|ui|{for behavior in SlideShowBehavior::ALL{let hint=match behavior{SlideShowBehavior::StopRestart=>"Stop the playlist when absent from every output. Showing it again restarts the first slide immediately.",SlideShowBehavior::PauseUnpause=>"Pause the playlist position while hidden and resume it when shown. An already-started transition can finish while hidden; GIF animation restarts when shown.",SlideShowBehavior::AlwaysPlay=>"Advance the playlist while hidden without loading or rendering hidden images. Showing it reveals the current slide; GIF animation restarts."};ui.selectable_value(&mut draft.behavior,behavior,crate::i18n::tr(ui,behavior.label())).on_hover_text(crate::i18n::tr(ui,hint));}}).response.labelled_by(caption.id).on_hover_text(crate::i18n::tr(ui,"Visibility is shared across all views using this source. Hidden playback retains timing metadata only."));
}
